class Solution {
    public int shortestSampler(int[] jars) {
        int n = jars.length, d = (int) Arrays.stream(jars).distinct().count(), best = n;
        for (int i = 0; i < n; i++) {
            Set<Integer> seen = new HashSet<>();
            for (int j = i; j < Math.min(n, i + best); j++) {
                seen.add(jars[j]);
                if (seen.size() == d) { best = j - i + 1; break; }
            }
        }
        return best;
    }
}

