code.c:
static int cmp_int(const void* a, const void* b) {
    int x = *(const int*) a, y = *(const int*) b;
    return (x > y) - (x < y);
}

static int* compress(const int* v, int n, int* distinct) {
    int* sorted = malloc(n * sizeof(int));
    memcpy(sorted, v, n * sizeof(int));
    qsort(sorted, n, sizeof(int), cmp_int);
    int d = 0;
    for (int i = 0; i < n; i++) if (i == 0 || sorted[i] != sorted[i - 1]) sorted[d++] = sorted[i];
    int* id = malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) id[i] = (int) ((int*) bsearch(&v[i], sorted, d, sizeof(int), cmp_int) - sorted);
    free(sorted);
    *distinct = d;
    return id;
}

int shortestSampler(int* jars, int jarsSize) {
    int n = jarsSize, d;
    int* id = compress(jars, n, &d);
    int* mark = calloc(d, sizeof(int));
    int best = n;
    for (int i = 0; i < n; i++) {
        int have = 0;
        for (int j = i; j < n && j < i + best; j++) {
            if (mark[id[j]] != i + 1) { mark[id[j]] = i + 1; have++; }
            if (have == d) { best = j - i + 1; break; }
        }
    }
    free(id); free(mark);
    return best;
}

