class Solution:
    def shortestSampler(self, jars: List[int]) -> int:
        d = len(set(jars))
        count, have, left, best = {}, 0, 0, len(jars)
        for i, f in enumerate(jars):
            count[f] = count.get(f, 0) + 1
            if count[f] == 1:
                have += 1
            while have == d:
                best = min(best, i - left + 1)
                g = jars[left]
                count[g] -= 1
                if count[g] == 0:
                    have -= 1
                left += 1
        return best

