class Solution {
    public int shortestSampler(int[] jars) {
        int n = jars.length, d = (int) Arrays.stream(jars).distinct().count();
        Map<Integer, Integer> count = new HashMap<>();
        int have = 0, left = 0, best = n;
        for (int i = 0; i < n; i++) {
            if (count.merge(jars[i], 1, Integer::sum) == 1) have++;
            while (have == d) {
                best = Math.min(best, i - left + 1);
                if (count.merge(jars[left++], -1, Integer::sum) == 0) have--;
            }
        }
        return best;
    }
}

