class Solution {
public:
    int shortestSampler(vector<int>& jars) {
        int n = jars.size(), d = unordered_set<int>(jars.begin(), jars.end()).size();
        unordered_map<int, int> count;
        int have = 0, left = 0, best = n;
        for (int i = 0; i < n; i++) {
            if (++count[jars[i]] == 1) have++;
            while (have == d) {
                best = min(best, i - left + 1);
                if (--count[jars[left++]] == 0) have--;
            }
        }
        return best;
    }
};

