int shortestSampler(int* jars, int jarsSize) {
    int n = jarsSize, d;
    int* id = compress(jars, n, &d);
    int* count = calloc(d, sizeof(int));
    int have = 0, left = 0, best = n;
    for (int i = 0; i < n; i++) {
        if (count[id[i]]++ == 0) have++;
        while (have == d) {
            if (i - left + 1 < best) best = i - left + 1;
            if (--count[id[left++]] == 0) have--;
        }
    }
    free(id); free(count);
    return best;
}
